<?php
require_once __DIR__ . '/funcoes_carrinho.php';
if ($_SERVER['REQUEST_METHOD']==='POST') {
  $acao=$_POST['acao']??'';
  if ($acao==='atualizar') { foreach(($_POST['quantidade']??[]) as $id=>$q) { $id=(int)$id; $q=(int)$q; if($id>0 && isset($_SESSION['ota_carrinho'][$id])) { if($q<1) unset($_SESSION['ota_carrinho'][$id]); else $_SESSION['ota_carrinho'][$id]=min(99,$q); } } }
  elseif($acao==='remover') { unset($_SESSION['ota_carrinho'][(int)($_POST['id_prod']??0)]); }
  elseif($acao==='limpar') { $_SESSION['ota_carrinho']=[]; }
  ota_redirect('carrinho.php');
}
$items=ota_cart_items($conn); $total=ota_cart_total($items); $aviso=$_SESSION['ota_aviso']??''; unset($_SESSION['ota_aviso']);
