alue="<?=$id?>"></form><?php endforeach; ?><form method="post" class="mt-3" onsubmit="return confirm('Deseja remover todos os produtos do carrinho?')"><input type="hidden" name="acao" value="limpar"><button class="btn btn-link text-danger p-0" type="submit">Esvaziar carrinho</button></form><?php endif; ?></section></div><div class="col-lg-4"><section class="panel"><h2 class="title2">Resumo do pedido</h2><div class="d-flex justify-content-between mb-3"><span>Produtos</span><strong><?=count($items)?></strong></div><div class="d-flex justify-content-between mb-3"><span>Subtotal</span><strong><?=ota_money($total)?></strong></div><div class="d-flex justify-content-between mb-3"><span>Entrega</span><span>A combinar</span></div><hr><div class="d-flex justify-content-between align-items-center"><strong>Total</strong><span class="total"><?=ota_money($total)?></span></div><?php if($items): ?><a class="btnota w-100 text-center mt-4" href="finalizar.php">Informar entrega <i class="bi bi-arrow-right"></i></a><?php else: ?><a class="btnota w-100 text-center mt-4" href="../../cardapio.php">Escolher produtos</a><?php endif; ?><p class="small text-secondary mt-3 mb-0"><i class="bi bi-info-circle"></i> O valor da entrega será combinado com a pastelaria.</p></section></div></div></main></body></html>
